-- Normalize the 128 non-overlapping 科教版 projects to their video-led kit instructions.
-- Generated from /tmp/explore-content-current.json snapshot. Apply only after content review and authorization via pnpm db:push.
BEGIN;
SET LOCAL request.jwt.claim.role = 'service_role';
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TEMP TABLE _science_kit_expected (
  project_id bigint PRIMARY KEY,
  title text NOT NULL,
  video_url text NOT NULL,
  materials jsonb NOT NULL,
  steps jsonb NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
  e record;
  current_materials jsonb;
  current_steps jsonb;
  keep_step_id bigint;
  fk record;
  has_refs boolean;
BEGIN
  IF (SELECT count(*) FROM _science_kit_expected) <> 128 THEN
    RAISE EXCEPTION 'science kit whitelist cardinality changed';
  END IF;

  -- Compare only fields this migration is allowed to touch. Other project edits may proceed.
  FOR e IN SELECT * FROM _science_kit_expected ORDER BY project_id LOOP
    PERFORM 1 FROM public.projects p WHERE p.id = e.project_id FOR UPDATE;
    IF NOT FOUND OR NOT EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = e.project_id
        AND p.title = e.title
        AND p.video_url = e.video_url
        AND p.status = 'approved'
        AND '科教版' = ANY (p.tags)
        AND NOT ('趣味实验' = ANY (p.tags))
    ) THEN
      RAISE EXCEPTION 'science kit project % changed since snapshot', e.project_id;
    END IF;

    PERFORM 1 FROM public.project_materials m WHERE m.project_id = e.project_id FOR UPDATE;
    SELECT jsonb_agg(jsonb_build_object(
      'id', m.id, 'material', m.material, 'project_id', m.project_id, 'sort_order', m.sort_order
    ) ORDER BY m.sort_order, m.id)
      INTO current_materials
      FROM public.project_materials m WHERE m.project_id = e.project_id;
    IF current_materials IS DISTINCT FROM e.materials THEN
      RAISE EXCEPTION 'science kit materials for project % changed since snapshot', e.project_id;
    END IF;

    PERFORM 1 FROM public.project_steps s WHERE s.project_id = e.project_id FOR UPDATE;
    SELECT jsonb_agg(jsonb_build_object(
      'id', s.id, 'title', s.title, 'image_url', s.image_url, 'project_id', s.project_id,
      'sort_order', s.sort_order, 'description', s.description
    ) ORDER BY s.sort_order, s.id)
      INTO current_steps
      FROM public.project_steps s WHERE s.project_id = e.project_id;
    IF current_steps IS DISTINCT FROM e.steps THEN
      RAISE EXCEPTION 'science kit steps for project % changed since snapshot', e.project_id;
    END IF;
  END LOOP;

  -- Refuse to delete a step that is referenced by any FK in the live schema.
  CREATE TEMP TABLE _science_kit_delete_step_ids (step_id bigint PRIMARY KEY) ON COMMIT DROP;
    SELECT (x.step->>'id')::bigint
    FROM _science_kit_expected ep
    CROSS JOIN LATERAL jsonb_array_elements(ep.steps) x(step)
    WHERE (x.step->>'id')::bigint <> (
      SELECT (first_step.step->>'id')::bigint
      FROM jsonb_array_elements(ep.steps) first_step(step)
      ORDER BY (first_step.step->>'sort_order')::integer, (first_step.step->>'id')::bigint
      LIMIT 1
    );
  FOR fk IN
    SELECT child_ns.nspname AS child_schema, child.relname AS child_table,
           child_col.attname AS child_column, array_length(c.conkey, 1) AS column_count
    FROM pg_constraint c
    JOIN pg_class child ON child.oid = c.conrelid
    JOIN pg_namespace child_ns ON child_ns.oid = child.relnamespace
    JOIN pg_class parent ON parent.oid = c.confrelid
    JOIN pg_namespace parent_ns ON parent_ns.oid = parent.relnamespace
    JOIN pg_attribute child_col ON child_col.attrelid = child.oid AND child_col.attnum = c.conkey[1]
    WHERE c.contype = 'f' AND parent_ns.nspname = 'public' AND parent.relname = 'project_steps'
      AND array_length(c.conkey, 1) = array_length(c.confkey, 1)
  LOOP
    IF fk.column_count > 1 THEN
      RAISE EXCEPTION 'composite FK %.% references project_steps; refusing step deletion',
        fk.child_table, fk.child_column;
    END IF;
    EXECUTE format(
      'SELECT EXISTS (SELECT 1 FROM %I.%I c JOIN pg_temp._science_kit_delete_step_ids e ON c.%I = e.step_id)',
      fk.child_schema, fk.child_table, fk.child_column
    ) INTO has_refs;
    IF has_refs THEN
      RAISE EXCEPTION 'science kit step references prevent deletion: %.%', fk.child_table, fk.child_column;
    END IF;
  END LOOP;
END $$;

CREATE TEMP TABLE _science_kit_keep_steps (project_id bigint PRIMARY KEY, step_id bigint NOT NULL) ON COMMIT DROP;
SELECT e.project_id, (SELECT s.id FROM public.project_steps s WHERE s.project_id = e.project_id ORDER BY s.sort_order, s.id LIMIT 1)
FROM _science_kit_expected e;

UPDATE public.project_materials m
SET material = format('《%s》对应实验材料包 1 套（需自行购买）', e.title)
FROM _science_kit_expected e
WHERE m.project_id = e.project_id;

UPDATE public.project_steps s
SET title = '观看实验视频',
    description = '请准备好对应实验材料包，跟随本页视频完成操作。',
    image_url = NULL,
    sort_order = 0
FROM _science_kit_expected e
JOIN _science_kit_keep_steps k ON k.project_id = e.project_id
WHERE s.id = k.step_id;

DELETE FROM public.project_steps s
USING _science_kit_keep_steps k
WHERE s.project_id = k.project_id AND s.id <> k.step_id;

UPDATE public.projects p
SET updated_at = now()
FROM _science_kit_expected e
WHERE p.id = e.project_id;

COMMIT;
