  (1301, '自制电动机', 'https://assets.steamx.cc/kejiao16a/六年级/013_自制电动机/video_1.mp4', $$[{"id":4892,"material":"（口播未提及）","project_id":1301,"sort_order":0}]$$::jsonb, $$[{"id":7152,"title":"步骤 1","image_url":null,"project_id":1301,"sort_order":0,"description":"放摩擦条将线圈的两端的包期线一头完全刮干净粘上3M胶,贴在泡沫板上在一片上插入带孔的小木块带孔的上上电池盒用3M.粘在刨沫板上电池盒的导线粘成U形差,并且插入小木块用双面胶把磁铁粘在线圈下方把磁铁粘在线圈下方再把线圈放在U型插上方装上电池,轻轻波动线圈线圈就一直转动"}]$$::jsonb),
  (1302, '蒸汽船', 'https://assets.steamx.cc/kejiao16a/六年级/014_蒸汽船/video_1.mp4', $$[{"id":4893,"material":"（口播未提及）","project_id":1302,"sort_order":0}]$$::jsonb, $$[{"id":7153,"title":"步骤 1","image_url":null,"project_id":1302,"sort_order":0,"description":"首先将2号板装在4号板上再将4号板装在1号板上2号板连接3号板并安装在1号板上在屏中装三分之二左右的水将瓶塞装在瓶口插入吸管注意吸管插入一点极客按视频操作将瓶子安装在架子上将双面胶粘在传体上方将目的板粘在传体上注意吸管朝下将蜡烛放在木板上调整一下位置在吸管尾部装上热缩管点燃蜡烛后用火加热收缩将传体放入水中等待水沸腾小传着行使啦"}]$$::jsonb),
  (1303, '红绿灯', 'https://assets.steamx.cc/kejiao16a/六年级/015_红绿灯/video_1.mp4', $$[{"id":4800,"material":"（见实验说明）","project_id":1303,"sort_order":0}]$$::jsonb, $$[{"id":6998,"title":"见视频","image_url":null,"project_id":1303,"sort_order":0,"description":"见视频"}]$$::jsonb),
  (1304, '机器霸王龙', 'https://assets.steamx.cc/kejiao16a/六年级/016_机器霸王龙/video_1.mp4', $$[{"id":4894,"material":"（口播未提及）","project_id":1304,"sort_order":0}]$$::jsonb, $$[{"id":7154,"title":"步骤 1","image_url":null,"project_id":1304,"sort_order":0,"description":"将电池盒的线穿过1号零件的孔中并连接接电机两端将2号零件安装在3号零件上定用螺丝�插入5号零件的孔中拿出另一块5安pls安�whereisthe5号零件安装上去在6号零件上面安装.7号零件固定好两端再把刚才拼装好的头部和尾部按视频操作拼装定用螺丝固定按视Iamusingthe8号零件拼装好两端用来固定孔龙的前面另一边也是一次重复操作安装15号零件在10号腿上固定好"}]$$::jsonb),
  (1305, '爬行机器人', 'https://assets.steamx.cc/kejiao16a/六年级/017_爬行机器人/video_1.mp4', $$[{"id":4895,"material":"（口播未提及）","project_id":1305,"sort_order":0}]$$::jsonb, $$[{"id":7155,"title":"步骤 1","image_url":null,"project_id":1305,"sort_order":0,"description":"首先按视频操作,将电池盒底板两边,凭接电池底板固定片,用3M胶固定住电池盒。将场传动轴,插入电池底板固定片孔中,并安装好车轮。再将短传动轴,传过中间的孔中,安装传动壁固定,安装黄色电片后,再安装传动壁"},{"id":7156,"title":"步骤 2","image_url":null,"project_id":1305,"sort_order":1,"description":"最后,用黄色电片固定好,另一边也一次重复操作。将电池盒陷于马达连接,注意红黑两线的连接方向。将马达固定箱分别安装在马达两侧,用长螺丝插入马达固定箱孔中,并用螺母固定好。3M胶将在马达上,把打头轴插入皮轮孔中。皮轮安装在马达孔中,并用短螺丝拧紧固定好。在马达的空间,皮轮也一次重复安装,注意打头轴方向。将两节部位,用长传动轴串起来,零用黄色电片固定两单。长传动轴穿过马达固定箱孔中,向皮筋安装在皮轮,和长传动轴上,零用黄色电片固定。另一边,一次重复操作,注意黄色电片在里侧"},{"id":7157,"title":"步骤 3","image_url":null,"project_id":1305,"sort_order":2,"description":"然后,两边安装好车轮,弹动壁连接打头轴,零用黄色电片固定。另一边也一次重复操作。将扭扭棒,按视频操作穿过孔中。相互交叉扭。再将泡沫球,安装在扭扭棒顶部。再泡沫球贴上眼睛。爬行机器人,就拼装完成啦!按下电池开关。一起看看效果吧!"}]$$::jsonb),
  (1306, '手摇发电机', 'https://assets.steamx.cc/kejiao16a/六年级/018_手摇发电机/video_1.mp4', $$[{"id":4896,"material":"（口播未提及）","project_id":1306,"sort_order":0}]$$::jsonb, $$[{"id":7158,"title":"步骤 1","image_url":null,"project_id":1306,"sort_order":0,"description":"字幕by索兰娅"}]$$::jsonb),
  (1307, '费纳奇镜', 'https://assets.steamx.cc/kejiao16a/六年级/019_费纳奇镜/video_1.mp4', $$[{"id":4897,"material":"（口播未提及）","project_id":1307,"sort_order":0}]$$::jsonb, $$[{"id":7159,"title":"步骤 1","image_url":null,"project_id":1307,"sort_order":0,"description":"将吸管套在木块上把小圆片插入木块后将上面的贴纸撕开"},{"id":7160,"title":"步骤 2","image_url":null,"project_id":1307,"sort_order":1,"description":"然后将大圆片安装到小圆片上方在纸片正面的最下面贴上双面胶将双面胶撕开用大圆片环要纸片捡起定将它固定在刚才贴好的双面胶上试试用右手轻捏吸管左手转动底部的木块吧"}]$$::jsonb),
  (1308, '三球仪', 'https://assets.steamx.cc/kejiao16a/六年级/020_三球仪/video_1.mp4', $$[{"id":4898,"material":"（口播未提及）","project_id":1308,"sort_order":0}]$$::jsonb, $$[{"id":7161,"title":"步骤 1","image_url":null,"project_id":1308,"sort_order":0,"description":"将一件安装在电机一侧插插电机两侧连接电池和红黑两线将组装的半成品插入4号零件孔中两侧用2号零件固定上方安装3号零件4号零件旁边4号零件中的1号零件4号零件4号零件和7号零件的凹槽处安装8号零件固定4号零件的中心孔中用9号零件固定电机在安装10号零件将11号零件和12号零件相互交叉拼接安装到14号零件上安装到14号零件和12号零件相互交叉拼接安装到15号零件上再把组装好的成品按视频操作安装到16号零件上按视频操作其余两个齿轮用17号零件固定再把刚才组装的半成品安装到铁肘上并用黄色电瓶固定在11号零件上安装18号零件再一次装上大泡墨球和小泡墨球用3M胶贴在电池和后面装上电池安装在6号零件上面三球一就拼装完成了按下开关一起看看效果吧"}]$$::jsonb),
  (1309, '牛顿摆', 'https://assets.steamx.cc/kejiao16a/六年级/021_牛顿摆/video_1.mp4', $$[{"id":4899,"material":"（口播未提及）","project_id":1309,"sort_order":0}]$$::jsonb, $$[{"id":7162,"title":"步骤 1","image_url":null,"project_id":1309,"sort_order":0,"description":"首先將拼板次,插入拼板一周將拼板兩,插入拼板次,和拼板一周拼板二周,B組將連線創意電片中去擺球插入拼板"}]$$::jsonb),
  (1310, '手摇起重机', 'https://assets.steamx.cc/kejiao16a/六年级/022_手摇起重机/video_1.mp4', $$[{"id":4900,"material":"（口播未提及）","project_id":1310,"sort_order":0}]$$::jsonb, $$[{"id":7163,"title":"步骤 1","image_url":null,"project_id":1310,"sort_order":0,"description":"首先,將5號零件插入1號零件3號零件,插入底部,組成底座然後,按視頻操作位置,用螺絲加固底部再用螺絲固定下"},{"id":7164,"title":"步骤 2","image_url":null,"project_id":1310,"sort_order":1,"description":"其次,把8號零件放在兩片4號零件中間中間用螺絲加固看視頻操作傳過傳動軸在4號零件的外側,裝黃色電篇固定另一側,安裝手搖零件B手搖零件B下方的孔中,再穿過傳動軸兩側分別安裝好黃色電篇固定再安裝手搖零件AB,連線需要綁在兩片黃色電篇中間綠線頭,用剪刀把它剪斷然後再安裝滑動輪將組裝好的手搖組件插入底座注意連線要穿過5號零件中間的孔洞"},{"id":7165,"title":"步骤 3","image_url":null,"project_id":1310,"sort_order":2,"description":"其次,按視頻操作組裝6號零件傳動軸兩側,用黃色電篇固定將明顯,按視頻操作放置下方再把剛才組裝的半成品插入底座後用螺絲加固接下來,按視頻操作用7號10號零件,組裝吊鉤組件兩側用黃色電篇固定好2號零件,9號零件,組裝支撐架組件先將傳動軸穿入遠孔中中間插入滑動輪兩側用黃色電篇固定好將組裝好的支撐架組件插入底座再用螺絲加固最後,將吊鉤組件穿入連線一圈後,打死結朋友們,也可以試一下,看看能吊起哪些東西吧"}]$$::jsonb),
  (1311, '齿轮往返车', 'https://assets.steamx.cc/kejiao16a/六年级/023_齿轮往返车/video_1.mp4', $$[{"id":4901,"material":"（口播未提及）","project_id":1311,"sort_order":0}]$$::jsonb, $$[{"id":7166,"title":"步骤 1","image_url":null,"project_id":1311,"sort_order":0,"description":"首先把硬件跟6号零件,用这个字注意短钉子的背面来装6号零件另外一个轮子,按照上一个步骤一次操作注意两边用短钉子中间的用强钉子安装"},{"id":7167,"title":"步骤 2","image_url":null,"project_id":1311,"sort_order":1,"description":"其次2号零件用短钉子组成两个轮子接下来分为0.0和3号零件用短钉子跟4号零件固定电池盒的导线,传过8号零件的小孔与电机连接而上一步组成的零件夹住电机单M胶丝下,贴在电池盒背面"},{"id":7168,"title":"步骤 3","image_url":null,"project_id":1311,"sort_order":2,"description":"然后将传动轴,传过车身的圆孔里再用黄色电片固定两端"},{"id":7169,"title":"步骤 4","image_url":null,"project_id":1311,"sort_order":3,"description":"然后两端再安装齿轮跟9号零件再将7号零件安装在车尾两个卡槽内"},{"id":7170,"title":"步骤 5","image_url":null,"project_id":1311,"sort_order":4,"description":"最后把之前安装好的轮子安装到卡槽内按照视频操作后,内侧用螺帽固定加开关,一起看看效果吧"}]$$::jsonb),
  (1314, '太阳能飞机', 'https://assets.steamx.cc/kejiao16a/六年级/026_太阳能飞机/video_1.mp4', $$[{"id":4902,"material":"（口播未提及）","project_id":1314,"sort_order":0}]$$::jsonb, $$[{"id":7171,"title":"步骤 1","image_url":null,"project_id":1314,"sort_order":0,"description":"首先按视频操作将9号8号零件组装成底座"},{"id":7172,"title":"步骤 2","image_url":null,"project_id":1314,"sort_order":1,"description":"其次把5号零件插入1号零件尾部"},{"id":7173,"title":"步骤 3","image_url":null,"project_id":1314,"sort_order":2,"description":"然后在太阳能板背部粘上3M胶按照视频操作位置粘在尾部组件接下来将3号4号零件插住电机插入尾部组件注意3号零件在上面4号零件在下面"},{"id":7174,"title":"步骤 4","image_url":null,"project_id":1314,"sort_order":3,"description":"其次按照视频操作将6号7号零件组装起来安装在太阳能飞机头部再把2号零件安装在头部两侧亮能板的红线接电机的黑线黑线接电机的红线"},{"id":7175,"title":"步骤 5","image_url":null,"project_id":1314,"sort_order":4,"description":"最后把组装好的底座组件插入机身再把齿轮插入电机后插入10号零件咱们一个太阳能飞机就组装完成了看看在太阳底下的效果吧你学会了吗一起来试一试"}]$$::jsonb),
  (1315, '天文望远镜', 'https://assets.steamx.cc/kejiao16a/初中/001_天文望远镜/video_1.mp4', $$[{"id":4903,"material":"（口播未提及）","project_id":1315,"sort_order":0}]$$::jsonb, $$[{"id":7176,"title":"步骤 1","image_url":null,"project_id":1315,"sort_order":0,"description":"首先拿出拼板2將拼板1插入拼板2孔位中去拿出拼板3將拼板1對準孔位插入拿出拼板4將短打頭軸插入中間的圓孔接著插入拼板3中的圓孔然後拿出電片按壓下去固定就可以了接下來拿出拼板19拼板13中的一根插入拼板19孔位中戴方孔朝上再拿出拼板18對應孔位插入接著拿出拼板12插入拼板13插入然後拼板12插入與相同那根對位安裝最後一根拼板13插入拼板19中去接著拿出拼板8穿過整體再拿出拼板6穿過整體看視頻操作將拼板17放入中間再將小金片放入再拿出拼板20對應拼板12插入孔位封頂裝好後就得到了視頻中的樣子看視頻找到拼板19那一端然後拿出拼板20億穿過拿出拼板9插入拼板8再拿出拼板7插入再接著拿拼板10其中一根插入拼板8和拼板7孔位中再拿拼板11插入拼板10剩餘兩根插入先將拼板21插好再將拼板9和拼板11插入拼板6的孔位中去看視頻拿拼板21穿過再將大金片放入再拿拼板16放入最後再將拼板5對應孔位插入拿出長打頭軸穿過拼板15其中的兩塊板的圓孔然後穿過拼板14中的小圓孔再穿過拼板15剩下的兩塊板的圓孔然後拿出電片固定即可看視頻中的操作將拼板15中的兩塊轉一下最後將其插入拼板9的孔位中去然後再將其插入之下拼板4的孔位中去成品就完成好了可以向視頻中的操作使用"}]$$::jsonb),
  (1316, '弩车', 'https://assets.steamx.cc/kejiao16a/初中/002_弩车/video_1.mp4', $$[{"id":4904,"material":"（口播未提及）","project_id":1316,"sort_order":0}]$$::jsonb, $$[{"id":7177,"title":"步骤 1","image_url":null,"project_id":1316,"sort_order":0,"description":"首先,降4號零件裝在兩個2號零件中間再拼接到1號零件上操作,降3號零件最差差入2號零件的孔中放在11號零件的孔7號零件再在上方安裝15號零件拼接在一起"}]$$::jsonb),
  (1321, '木质显微镜', 'https://assets.steamx.cc/kejiao16a/初中/007_木质显微镜/video_1.mp4', $$[{"id":4905,"material":"（口播未提及）","project_id":1321,"sort_order":0}]$$::jsonb, $$[{"id":7178,"title":"步骤 1","image_url":null,"project_id":1321,"sort_order":0,"description":"第一步將晶片撕掉保護膜貼在小板上"},{"id":7179,"title":"步骤 2","image_url":null,"project_id":1321,"sort_order":1,"description":"第二步 will put the晶片小板插在兩個小板之間安裝在地板塊的一側領用6毫米螺絲固定將兩塊小板安裝支架方孔內領用6毫米螺絲固定和網行支架圓孔組合在一起60毫米螺絲和防止固定一下小孔固定幫助接下來將放置綠綿"}]$$::jsonb),
  (1322, '万有引力', 'https://assets.steamx.cc/kejiao16a/初中/008_万有引力/video_1.mp4', $$[{"id":4906,"material":"（口播未提及）","project_id":1322,"sort_order":0}]$$::jsonb, $$[{"id":7180,"title":"步骤 1","image_url":null,"project_id":1322,"sort_order":0,"description":"連將船型開關安裝在一號板上將單跟導線和電池和紅線分別連接在開關上將電池和黑線和單跟導線另一頭連接馬達一紅黑導線不要接板了安裝在二號板上注意二號板塗一號潮上潮潮上一號板圓孔中整理好導線把底座支架安裝在一號板上注意木板貨口正好對準馬達塗漆點馬達軸上把頭軸陰陽點綴固定好把七號板插入六號板凹槽內注意板子的插入潮下安裝在七號板上注意新對準所有塗槽將安裝在八號板卡槽上注意插入四個空卡槽操作插入十號板插上十一號板然後插上十二號板紙鐵放在十二號板的兩側放到十三號板的卡槽內再安裝泡沫球固定住紙鐵注意組裝後測試一下紙鐵能不能相信將紅色穿過十三號板孔中並打擊記號只和拿出來安裝電池再放進去再將紅色套在十號板卡槽內泡沫球小板就懸浮起來啦最後放上地球模型看看效果吧換個角度看一下吧"}]$$::jsonb),
  (1323, '轨道卫星', 'https://assets.steamx.cc/kejiao16a/初中/009_轨道卫星/video_1.mp4', $$[{"id":4907,"material":"（口播未提及）","project_id":1323,"sort_order":0}]$$::jsonb, $$[{"id":7181,"title":"步骤 1","image_url":null,"project_id":1323,"sort_order":0,"description":"先將2號板和3號板組裝成底座支架後支架上安裝1號板然後把傳行開關安裝在1號板孔內將單紙導線和電池盒紅線擰在開關體片上助力兩邊接頭零緊不要觸碰到用3M膠將電池盒固定在底板上同合兩線從1號板孔中穿出後連接馬達固定6號就不要插得太緊兩側安裝13號板注意方孔朝向用把頭軸穿過12號板和9號板後用電片固定然後安裝在14號板再再塗骨安裝15號板用16號板插入兩側方孔中按時停操作將14號板安裝在10號板上把地球模型安裝在鐵軸上最後安裝電池軌道衛星就拼裝完成了一起看看效果吧"}]$$::jsonb),
